pub fn get_environment_bool_variable(arg_name: [*c]const u8) callconv(.c) bool {
    @setEvalBranchQuota(100000);
    var name = arg_name;
    _ = &name;
    var var_string: [*c]const u8 = SDL_GetEnvironmentVariable(SDL_GetEnvironment(), name);
    _ = &var_string;
    if (!(var_string != null) or (@as(c_int, var_string[@as(c_int, 0)]) == @as(c_int, '\x00'))) {
        return @"false" != 0;
    }
    return @"true" != 0;
}
