pub export fn SDLTest_CommonLogUsage(arg_state: [*c]SDLTest_CommonState, arg_argv0: [*c]const u8, arg_options: [*c][*c]const u8) void {
    @setEvalBranchQuota(100000);
    var state = arg_state;
