    var argv0 = arg_argv0;
    _ = &argv0;
    var options = arg_options;
    _ = &options;
    var argparser: [*c]SDLTest_ArgumentParser = undefined;
    _ = &argparser;
    SDL_Log("USAGE: %s", argv0);
    {
        argparser = state.*.argparser;
        while (argparser != null) : (argparser = argparser.*.next) {
            if (argparser.*.finalize != null) {
                argparser.*.finalize.?(argparser.*.data);
