            if (argparser.*.usage != null) {
                var i: c_int = undefined;
                _ = &i;
                {
                    i = 0;
                    while (@as(?*anyopaque, @ptrCast(@alignCast(@constCast(argparser.*.usage[@bitCast(@as(isize, @intCast(i)))])))) != @as(?*anyopaque, null)) : (i += 1) {
                        SDL_Log("    %s", argparser.*.usage[@bitCast(@as(isize, @intCast(i)))]);
                    }
                }
            }
        }
    }
    if (options != null) {
        var i: c_int = undefined;
        _ = &i;
        {
            i = 0;
            while (@as(?*anyopaque, @ptrCast(@alignCast(@constCast(options[@bitCast(@as(isize, @intCast(i)))])))) != @as(?*anyopaque, null)) : (i += 1) {
