pub export fn SDLTest_CommonDefaultArgs(arg_state: [*c]SDLTest_CommonState, arg_argc: c_int, arg_argv: [*c][*c]u8) bool {
    @setEvalBranchQuota(100000);
    var state = arg_state;
    _ = &state;
    var argc = arg_argc;
    _ = &argc;
    var argv = arg_argv;
    _ = &argv;
    var i: c_int = 1;
    _ = &i;
    while (i < argc) {
        const consumed: c_int = SDLTest_CommonArg(state, i);
        _ = &consumed;
        if (consumed <= @as(c_int, 0)) {
            SDLTest_CommonLogUsage(state, argv[@as(c_int, 0)], null);
            return @"false" != 0;
        }
        i += consumed;
    }
    return @"true" != 0;
}
pub fn SDLTest_PrintDisplayOrientation(arg_text: [*c]u8, arg_maxlen: usize, arg_orientation: SDL_DisplayOrientation) callconv(.c) void {
