pub fn SDLTest_PrintRenderer(arg_renderer: ?*SDL_Renderer) callconv(.c) void {
    @setEvalBranchQuota(100000);
    var renderer = arg_renderer;
    _ = &renderer;
    var name: [*c]const u8 = undefined;
    _ = &name;
    var i: c_int = undefined;
    _ = &i;
    var text: [1024]u8 = undefined;
    _ = &text;
    var max_texture_size: c_int = undefined;
    _ = &max_texture_size;
    var texture_formats: [*c]const SDL_PixelFormat = undefined;
    _ = &texture_formats;
    name = SDL_GetRendererName(renderer);
    SDL_Log("  Renderer %s:", name);
    if (SDL_strcmp(name, "gpu") == @as(c_int, 0)) {
        var device: ?*SDL_GPUDevice = @ptrCast(@alignCast(SDL_GetPointerProperty(SDL_GetRendererProperties(renderer), "SDL.renderer.gpu.device", null)));
        _ = &device;
        SDL_Log("    Driver: %s", SDL_GetGPUDeviceDriver(device));
    }
    SDL_Log("    VSync: %d", @as(c_int, @truncate(SDL_GetNumberProperty(SDL_GetRendererProperties(renderer), "SDL.renderer.vsync", 0))));
    texture_formats = @ptrCast(@alignCast(SDL_GetPointerProperty(SDL_GetRendererProperties(renderer), "SDL.renderer.texture_formats", null)));
    if (texture_formats != null) {
        _ = SDL_snprintf(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), "    Texture formats: ");
        {
            i = 0;
            while (texture_formats[@bitCast(@as(isize, @intCast(i)))] != 0) : (i += 1) {
                if (i > @as(c_int, 0)) {
                    SDL_snprintfcat(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), ", ");
                }
                SDLTest_PrintPixelFormat(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), texture_formats[@bitCast(@as(isize, @intCast(i)))]);
            }
        }
        SDL_Log("%s", @as([*c]u8, @ptrCast(@alignCast(&text))));
    }
    max_texture_size = @truncate(SDL_GetNumberProperty(SDL_GetRendererProperties(renderer), "SDL.renderer.max_texture_size", 0));
    if (max_texture_size != 0) {
        SDL_Log("    Max Texture Size: %dx%d", max_texture_size, max_texture_size);
    }
}
pub fn SDLTest_LoadIcon(arg_file: [*c]const u8) callconv(.c) [*c]SDL_Surface {
