pub fn SDLTest_ExampleHitTestCallback(arg_win: ?*SDL_Window, arg_area: [*c]const SDL_Point, arg_data: ?*anyopaque) callconv(.c) SDL_HitTestResult {
    @setEvalBranchQuota(100000);
    var win = arg_win;
    _ = &win;
    var area = arg_area;
    _ = &area;
    var data = arg_data;
    _ = &data;
    var w: c_int = undefined;
    _ = &w;
    var h: c_int = undefined;
    _ = &h;
    const RESIZE_BORDER: c_int = 8;
    _ = &RESIZE_BORDER;
    const DRAGGABLE_TITLE: c_int = 32;
    _ = &DRAGGABLE_TITLE;
    _ = SDL_GetWindowSize(win, &w, &h);
    if (area.*.x < RESIZE_BORDER) {
        if (area.*.y < RESIZE_BORDER) {
            SDL_Log("SDL_HITTEST_RESIZE_TOPLEFT");
            return SDL_HITTEST_RESIZE_TOPLEFT;
        } else if (area.*.y >= (h - RESIZE_BORDER)) {
            SDL_Log("SDL_HITTEST_RESIZE_BOTTOMLEFT");
            return SDL_HITTEST_RESIZE_BOTTOMLEFT;
        } else {
            SDL_Log("SDL_HITTEST_RESIZE_LEFT");
            return SDL_HITTEST_RESIZE_LEFT;
        }
    } else if (area.*.x >= (w - RESIZE_BORDER)) {
        if (area.*.y < RESIZE_BORDER) {
            SDL_Log("SDL_HITTEST_RESIZE_TOPRIGHT");
            return SDL_HITTEST_RESIZE_TOPRIGHT;
        } else if (area.*.y >= (h - RESIZE_BORDER)) {
            SDL_Log("SDL_HITTEST_RESIZE_BOTTOMRIGHT");
            return SDL_HITTEST_RESIZE_BOTTOMRIGHT;
        } else {
            SDL_Log("SDL_HITTEST_RESIZE_RIGHT");
            return SDL_HITTEST_RESIZE_RIGHT;
        }
    } else if (area.*.y >= (h - RESIZE_BORDER)) {
        SDL_Log("SDL_HITTEST_RESIZE_BOTTOM");
        return SDL_HITTEST_RESIZE_BOTTOM;
    } else if (area.*.y < RESIZE_BORDER) {
        SDL_Log("SDL_HITTEST_RESIZE_TOP");
        return SDL_HITTEST_RESIZE_TOP;
    } else if (area.*.y < DRAGGABLE_TITLE) {
        SDL_Log("SDL_HITTEST_DRAGGABLE");
        return SDL_HITTEST_DRAGGABLE;
    }
    return SDL_HITTEST_NORMAL;
}
pub export fn SDLTest_CommonInit(arg_state: [*c]SDLTest_CommonState) bool {
    @setEvalBranchQuota(100000);
    var state = arg_state;
    _ = &state;
    var i: c_int = undefined;
    _ = &i;
    var j: c_int = undefined;
    _ = &j;
    var m: c_int = undefined;
    _ = &m;
    var n: c_int = undefined;
    _ = &n;
    var w: c_int = undefined;
    _ = &w;
    var h: c_int = undefined;
    _ = &h;
    var text: [1024]u8 = undefined;
    _ = &text;
    if ((state.*.flags & SDL_INIT_VIDEO) != 0) {
        if ((state.*.verbose & @as(SDLTest_VerboseFlags, VERBOSE_VIDEO)) != 0) {
            n = SDL_GetNumVideoDrivers();
            if (n == @as(c_int, 0)) {
                SDL_Log("No built-in video drivers");
            } else {
                _ = SDL_snprintf(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), "Built-in video drivers:");
                {
                    i = 0;
                    while (i < n) : (i += 1) {
                        if (i > @as(c_int, 0)) {
                            SDL_snprintfcat(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), ",");
                        }
                        SDL_snprintfcat(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), " %s", SDL_GetVideoDriver(i));
                    }
                }
                SDL_Log("%s", @as([*c]u8, @ptrCast(@alignCast(&text))));
            }
        }
        if (!SDL_InitSubSystem(SDL_INIT_VIDEO)) {
            SDL_Log("Couldn't initialize video driver: %s", SDL_GetError());
            return @"false" != 0;
        }
        if ((state.*.verbose & @as(SDLTest_VerboseFlags, VERBOSE_VIDEO)) != 0) {
            SDL_Log("Video driver: %s", SDL_GetCurrentVideoDriver());
        }
        _ = SDL_GL_SetAttribute(SDL_GL_RED_SIZE, state.*.gl_red_size);
        _ = SDL_GL_SetAttribute(SDL_GL_GREEN_SIZE, state.*.gl_green_size);
        _ = SDL_GL_SetAttribute(SDL_GL_BLUE_SIZE, state.*.gl_blue_size);
        _ = SDL_GL_SetAttribute(SDL_GL_ALPHA_SIZE, state.*.gl_alpha_size);
        _ = SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER, state.*.gl_double_buffer);
        _ = SDL_GL_SetAttribute(SDL_GL_BUFFER_SIZE, state.*.gl_buffer_size);
        _ = SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE, state.*.gl_depth_size);
        _ = SDL_GL_SetAttribute(SDL_GL_STENCIL_SIZE, state.*.gl_stencil_size);
        _ = SDL_GL_SetAttribute(SDL_GL_ACCUM_RED_SIZE, state.*.gl_accum_red_size);
        _ = SDL_GL_SetAttribute(SDL_GL_ACCUM_GREEN_SIZE, state.*.gl_accum_green_size);
        _ = SDL_GL_SetAttribute(SDL_GL_ACCUM_BLUE_SIZE, state.*.gl_accum_blue_size);
        _ = SDL_GL_SetAttribute(SDL_GL_ACCUM_ALPHA_SIZE, state.*.gl_accum_alpha_size);
        _ = SDL_GL_SetAttribute(SDL_GL_STEREO, state.*.gl_stereo);
        _ = SDL_GL_SetAttribute(SDL_GL_CONTEXT_RELEASE_BEHAVIOR, state.*.gl_release_behavior);
        _ = SDL_GL_SetAttribute(SDL_GL_MULTISAMPLEBUFFERS, state.*.gl_multisamplebuffers);
        _ = SDL_GL_SetAttribute(SDL_GL_MULTISAMPLESAMPLES, state.*.gl_multisamplesamples);
        if (state.*.gl_accelerated >= @as(c_int, 0)) {
            _ = SDL_GL_SetAttribute(SDL_GL_ACCELERATED_VISUAL, state.*.gl_accelerated);
        }
        _ = SDL_GL_SetAttribute(SDL_GL_RETAINED_BACKING, state.*.gl_retained_backing);
        if (state.*.gl_major_version != 0) {
            _ = SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION, state.*.gl_major_version);
            _ = SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION, state.*.gl_minor_version);
        }
        if (state.*.gl_debug != 0) {
            _ = SDL_GL_SetAttribute(SDL_GL_CONTEXT_FLAGS, SDL_GL_CONTEXT_DEBUG_FLAG);
        }
        if (state.*.gl_profile_mask != 0) {
            _ = SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK, state.*.gl_profile_mask);
        }
        if ((state.*.verbose & @as(SDLTest_VerboseFlags, VERBOSE_MODES)) != 0) {
            var displays: [*c]SDL_DisplayID = undefined;
            _ = &displays;
            var bounds: SDL_Rect = undefined;
            _ = &bounds;
            var usablebounds: SDL_Rect = undefined;
            _ = &usablebounds;
            var modes: [*c][*c]SDL_DisplayMode = undefined;
            _ = &modes;
            var mode: [*c]const SDL_DisplayMode = undefined;
            _ = &mode;
            var bpp: c_int = undefined;
            _ = &bpp;
            var Rmask: Uint32 = undefined;
            _ = &Rmask;
            var Gmask: Uint32 = undefined;
            _ = &Gmask;
            var Bmask: Uint32 = undefined;
            _ = &Bmask;
            var Amask: Uint32 = undefined;
            _ = &Amask;
            displays = SDL_GetDisplays(&n);
            SDL_Log("Number of displays: %d", n);
            {
                i = 0;
                while (i < n) : (i += 1) {
                    var displayID: SDL_DisplayID = displays[@bitCast(@as(isize, @intCast(i)))];
                    _ = &displayID;
                    SDL_Log("Display %u: %s", displayID, SDL_GetDisplayName(displayID));
                    _ = memset(@ptrCast(@alignCast(&bounds)), 0, @sizeOf(@TypeOf(bounds)));
                    _ = SDL_GetDisplayBounds(displayID, &bounds);
                    _ = memset(@ptrCast(@alignCast(&usablebounds)), 0, @sizeOf(@TypeOf(usablebounds)));
                    _ = SDL_GetDisplayUsableBounds(displayID, &usablebounds);
                    SDL_Log("Bounds: %dx%d at %d,%d", bounds.w, bounds.h, bounds.x, bounds.y);
                    SDL_Log("Usable bounds: %dx%d at %d,%d", usablebounds.w, usablebounds.h, usablebounds.x, usablebounds.y);
                    mode = SDL_GetDesktopDisplayMode(displayID);
                    _ = SDL_GetMasksForPixelFormat(mode.*.format, &bpp, &Rmask, &Gmask, &Bmask, &Amask);
                    SDL_Log("  Desktop mode: %dx%d@%gx %gHz, %d bits-per-pixel (%s)", mode.*.w, mode.*.h, mode.*.pixel_density, mode.*.refresh_rate, bpp, SDL_GetPixelFormatName(mode.*.format));
                    if ((@as(Uint32, @bitCast(@as(c_int, @intFromBool((Rmask != 0) or (Gmask != 0))))) != 0) or (Bmask != 0)) {
                        SDL_Log("      Red Mask   = 0x%.8x", Rmask);
                        SDL_Log("      Green Mask = 0x%.8x", Gmask);
                        SDL_Log("      Blue Mask  = 0x%.8x", Bmask);
                        if (Amask != 0) {
                            SDL_Log("      Alpha Mask = 0x%.8x", Amask);
                        }
                    }
                    modes = SDL_GetFullscreenDisplayModes(displayID, &m);
                    if (m == @as(c_int, 0)) {
                        SDL_Log("No available fullscreen video modes");
                    } else {
                        SDL_Log("  Fullscreen video modes:");
                        {
                            j = 0;
                            while (j < m) : (j += 1) {
                                mode = modes[@bitCast(@as(isize, @intCast(j)))];
                                _ = SDL_GetMasksForPixelFormat(mode.*.format, &bpp, &Rmask, &Gmask, &Bmask, &Amask);
                                SDL_Log("    Mode %d: %dx%d@%gx %gHz, %d bits-per-pixel (%s)", j, mode.*.w, mode.*.h, mode.*.pixel_density, mode.*.refresh_rate, bpp, SDL_GetPixelFormatName(mode.*.format));
                                if ((@as(Uint32, @bitCast(@as(c_int, @intFromBool((Rmask != 0) or (Gmask != 0))))) != 0) or (Bmask != 0)) {
                                    SDL_Log("        Red Mask   = 0x%.8x", Rmask);
                                    SDL_Log("        Green Mask = 0x%.8x", Gmask);
                                    SDL_Log("        Blue Mask  = 0x%.8x", Bmask);
                                    if (Amask != 0) {
                                        SDL_Log("        Alpha Mask = 0x%.8x", Amask);
                                    }
                                }
                            }
                        }
                    }
                    SDL_free(@ptrCast(@alignCast(modes)));
                }
            }
            SDL_free(@ptrCast(@alignCast(displays)));
        }
        if ((state.*.verbose & @as(SDLTest_VerboseFlags, VERBOSE_RENDER)) != 0) {
            n = SDL_GetNumRenderDrivers();
            if (n == @as(c_int, 0)) {
                SDL_Log("No built-in render drivers");
            } else {
                SDL_Log("Built-in render drivers:");
                {
                    i = 0;
                    while (i < n) : (i += 1) {
                        SDL_Log("  %s", SDL_GetRenderDriver(i));
                    }
                }
            }
        }
        state.*.displayID = SDL_GetPrimaryDisplay();
        if (state.*.display_index > @as(c_int, 0)) {
            var displays: [*c]SDL_DisplayID = SDL_GetDisplays(&n);
            _ = &displays;
            if (state.*.display_index < n) {
                state.*.displayID = displays[@bitCast(@as(isize, @intCast(state.*.display_index)))];
            }
            SDL_free(@ptrCast(@alignCast(displays)));
            if ((@as(c_uint, @bitCast(@as(c_int, state.*.window_x))) & @as(c_uint, 4294901760)) == SDL_WINDOWPOS_UNDEFINED_MASK) {
                state.*.window_x = @bitCast(@as(c_uint, @truncate(SDL_WINDOWPOS_UNDEFINED_MASK | state.*.displayID)));
                state.*.window_y = @bitCast(@as(c_uint, @truncate(SDL_WINDOWPOS_UNDEFINED_MASK | state.*.displayID)));
            } else if ((@as(c_uint, @bitCast(@as(c_int, state.*.window_x))) & @as(c_uint, 4294901760)) == SDL_WINDOWPOS_CENTERED_MASK) {
                state.*.window_x = @bitCast(@as(c_uint, @truncate(SDL_WINDOWPOS_CENTERED_MASK | state.*.displayID)));
                state.*.window_y = @bitCast(@as(c_uint, @truncate(SDL_WINDOWPOS_CENTERED_MASK | state.*.displayID)));
            }
        }
        {
            var include_high_density_modes: bool = @"false" != 0;
            _ = &include_high_density_modes;
            if ((state.*.window_flags & @as(c_ulong, 8192)) != 0) {
                include_high_density_modes = @"true" != 0;
            }
            _ = SDL_GetClosestFullscreenDisplayMode(state.*.displayID, state.*.window_w, state.*.window_h, state.*.refresh_rate, include_high_density_modes, &state.*.fullscreen_mode);
