        state.*.windows = @ptrCast(@alignCast(SDL_calloc(@bitCast(@as(c_long, state.*.num_windows)), @sizeOf(@TypeOf(state.*.windows.*)))));
        state.*.renderers = @ptrCast(@alignCast(SDL_calloc(@bitCast(@as(c_long, state.*.num_windows)), @sizeOf(@TypeOf(state.*.renderers.*)))));
        state.*.targets = @ptrCast(@alignCast(SDL_calloc(@bitCast(@as(c_long, state.*.num_windows)), @sizeOf(@TypeOf(state.*.targets.*)))));
        if (!(state.*.windows != null) or !(state.*.renderers != null)) {
            SDL_Log("Out of memory!");
            return @"false" != 0;
        }
        {
            i = 0;
