pub fn SDLTest_ScreenShotClipboardProvider(arg_context: ?*anyopaque, arg_mime_type: [*c]const u8, arg_size: [*c]usize) callconv(.c) ?*const anyopaque {
    @setEvalBranchQuota(100000);
    var context = arg_context;
    _ = &context;
