            _ = SDL_CloseIO(file);
            if (image != null) {
                data.*.image = image;
                data.*.size = length;
            }
        } else {
            SDL_Log("Couldn't load %s: %s", @as([*c]u8, @as([*c]u8, @constCast("screenshot.bmp"))), SDL_GetError());
        }
    }
    size.* = data.*.size;
    return data.*.image;
}
