    if (state != null) {
        var i: c_int = undefined;
        _ = &i;
        if (state.*.targets != null) {
            {
                i = 0;
                while (i < state.*.num_windows) : (i += 1) {
                    if (state.*.targets[@bitCast(@as(isize, @intCast(i)))] != null) {
                        SDL_DestroyTexture(state.*.targets[@bitCast(@as(isize, @intCast(i)))]);
                    }
                }
            }
            SDL_free(@ptrCast(@alignCast(state.*.targets)));
        }
        if (state.*.renderers != null) {
            {
                i = 0;
                while (i < state.*.num_windows) : (i += 1) {
                    if (state.*.renderers[@bitCast(@as(isize, @intCast(i)))] != null) {
                        SDL_DestroyRenderer(state.*.renderers[@bitCast(@as(isize, @intCast(i)))]);
                    }
                }
            }
            SDL_free(@ptrCast(@alignCast(state.*.renderers)));
        }
        if (state.*.windows != null) {
            {
                i = 0;
                while (i < state.*.num_windows) : (i += 1) {
                    SDL_DestroyWindow(state.*.windows[@bitCast(@as(isize, @intCast(i)))]);
                }
            }
            SDL_free(@ptrCast(@alignCast(state.*.windows)));
        }
        if (state.*.quit_after_ms_timer != 0) {
            _ = SDL_RemoveTimer(state.*.quit_after_ms_timer);
        }
    }
    SDL_Quit();
    SDLTest_CommonDestroyState(state);
}
pub export fn SDLTest_CommonDrawWindowInfo(arg_renderer: ?*SDL_Renderer, arg_window: ?*SDL_Window, arg_usedHeight: [*c]f32) void {
    @setEvalBranchQuota(100000);
    var renderer = arg_renderer;
    _ = &renderer;
    var window = arg_window;
    _ = &window;
    var usedHeight = arg_usedHeight;
    _ = &usedHeight;
    var text: [1024]u8 = undefined;
    _ = &text;
    var textY: f32 = 0.0;
    _ = &textY;
    const lineHeight: c_int = 10;
    _ = &lineHeight;
    var x: c_int = undefined;
    _ = &x;
    var y: c_int = undefined;
    _ = &y;
    var w: c_int = undefined;
    _ = &w;
    var h: c_int = undefined;
    _ = &h;
    var fx: f32 = undefined;
    _ = &fx;
    var fy: f32 = undefined;
