    SDLTest_PrintLogicalPresentation(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), logical_presentation);
    textY += @floatFromInt(lineHeight);
    _ = SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
