    textY += @floatFromInt(lineHeight);
    _ = SDL_SetRenderDrawColor(renderer, 170, 170, 170, 255);
    _ = SDL_GetWindowPosition(window, &x, &y);
    _ = SDL_snprintf(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), "SDL_GetWindowPosition: %d,%d", x, y);
    _ = SDLTest_DrawString(renderer, 0.0, textY, @ptrCast(@alignCast(&text)));
    textY += @floatFromInt(lineHeight);
    _ = SDL_GetWindowSize(window, &w, &h);
