    SDLTest_PrintWindowFlags(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), SDL_GetWindowFlags(window));
    _ = SDLTest_DrawString(renderer, 0.0, textY, @ptrCast(@alignCast(&text)));
    textY += @floatFromInt(lineHeight);
    mode = SDL_GetWindowFullscreenMode(window);
