        _ = SDL_snprintf(@ptrCast(@alignCast(&text)), @sizeOf(@TypeOf(text)), "SDL_GetWindowFullscreenMode: %dx%d@%gx %gHz, (%s)", mode.*.w, mode.*.h, mode.*.pixel_density, mode.*.refresh_rate, SDL_GetPixelFormatName(mode.*.format));
